export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

export { LoghubLogger } from './logger.js';
export type { LoghubLoggerOptions } from './logger.js';

export async function loghubLog(params: {
  service: string;
  app: string;
  env: string;
  level: LogLevel;
  message: string | object;
  attrs?: Record<string, any>;
}) {
  const baseUrl = process.env.LOGHUB_URL;
  const source = process.env.LOGHUB_SOURCE;
  const key = process.env.LOGHUB_KEY;

  if (!baseUrl || !source || !key) return;

  const payload = {
    ...params,
    message: typeof params.message === 'string' ? params.message : JSON.stringify(params.message),
  };

  try {
    await fetch(`${baseUrl}/ingest/log`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-loghub-source': source,
        'x-loghub-key': key,
      },
      body: JSON.stringify(payload),
    });
  } catch {
    // fail-safe: never crash app because logging failed
  }
}
